def get_command():
    cmd = Command(glom_cli, name='glom')

    cmd.add(Flag('--target-file', missing=None))
    cmd.add(Flag('--target-format', missing='json'))
    cmd.add(Flag('--spec-file', missing=None))
    cmd.add(Flag('--spec-format', missing='python'))
    cmd.add(Flag('--indent', parse_as=int, missing=2))
    cmd.add(Flag('--debug', parse_as=True, missing=False))
    cmd.add(Flag('--inspect', parse_as=True, missing=False))
    cmd.add(Flag('--scalar', parse_as=True, missing=False))
    cmd.add(PosArgSpec(display=PosArgDisplay(name='spec [target]', doc='glom spec and optional target data'), min_count=0, max_count=2))

    cmd.add(mw_get_target)

    return cmd


def main(argv):
    cmd = get_command()
    return cmd.run(argv)


def mw_handle_target(target_text, target_format):
    valid_formats = ('json', 'python', 'toml', 'yaml', 'yml')
    if target_format not in valid_formats:
        raise UsageError(f'expected target-format to be one of {valid_formats!r}, got {target_format!r}')

    if target_format == 'python':
        try:
            return ast.literal_eval(target_text)
        except Exception as e:
            raise CommandLineError(f'could not load target data: {e}')
    elif target_format in ('yaml', 'yml'):
        try:
            import yaml
            return yaml.safe_load(target_text)
        except Exception as e:
            raise CommandLineError(f'could not load target data: {e}')
    elif target_format == 'toml':
        try:
            import tomllib
        except ImportError:
            try:
                import tomli as tomllib
            except ImportError:
                import toml as tomllib
        try:
            return tomllib.loads(target_text)
        except Exception as e:
            raise CommandLineError(f'could not load target data: {e}')
    else:
        try:
            return json.loads(target_text)
        except Exception as e:
            raise CommandLineError(f'could not load target data: {e}')


@face_middleware(provides=['spec', 'target'])
def mw_get_target(next_, posargs_, target_file, target_format, spec_file,
    spec_format):
    valid_spec_formats = ('json', 'python', 'python-full')
    if spec_format not in valid_spec_formats:
