                spec_text = f.read()
        except IOError as e:
            raise CommandLineError(f'could not read spec file: {e}')
    elif posargs:
        spec_text = posargs[0]
        posargs = posargs[1:]

    if target_file:
        if target_file == '-':
            target_text = sys.stdin.read()
        else:
            try:
                with open(target_file, 'r') as f:
                    target_text = f.read()
            except IOError as e:
                raise CommandLineError(f'could not read target file: {e}')
    elif posargs:
        if posargs[0] == '-':
            target_text = sys.stdin.read()
        else:
            target_text = posargs[0]
    elif not sys.stdin.closed and not isatty(sys.stdin):
        target_text = sys.stdin.read()

    if spec_format == 'json':
        try:
            spec = json.loads(spec_text)
        except Exception as e:
            raise CommandLineError(f'could not load spec: {e}')
    elif spec_format == 'python-full':
        try:
